const main=document.querySelector('main');let projects=[];const groups={point:{name:'Point Media',role:'Diretor de Arte',period:'2025 — 2026',color:'#f24b30',desc:'Direção de arte, conceitos visuais e desdobramentos para campanhas. Uma seleção de trabalhos desenvolvidos na Point Media.'},truther:{name:'Truther',role:'UX/UI Designer',period:'2024 — 2025',color:'#c4bfba',desc:'Identidade de marca e experiências digitais. Projetos desenvolvidos na Truther Rezolve.ai.'},etec:{name:'ETEC de Poá',role:'Professor de Marketing',period:'2024 — 2025',color:'#d7cab6',desc:'Docência na formação técnica: ferramentas digitais aplicadas ao marketing, orientação de TCCs e desenvolvimento de competências criativas.'},norte:{name:'Norte Marketing',role:'Analista de Marketing',period:'2021 — 2024',color:'#aea99c',desc:'Comunicação visual, campanhas e peças digitais desenvolvidas na Norte Marketing.'},freelas:{name:'Freelas',role:'Projetos independentes',period:'Seleção de trabalhos',color:'#f24b30',desc:'Um espaço para explorar outras linguagens. Identidades, embalagens, campanhas e peças desenvolvidas em projetos independentes.'}};
const WA='https://wa.me/5511957750903';
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function mosaic(items){let rows=[],i=0;const piece=it=>`<a class="artwork" href="${esc(it.src)}" target="_blank" rel="noopener" aria-label="Ampliar ${esc(it.alt)}"><img src="${esc(it.src)}" width="${it.w}" height="${it.h}" alt="${esc(it.alt)}" loading="lazy" decoding="async"><span>Ampliar ↗</span></a>`;while(i<items.length){const a=items[i],b=items[i+1];const full=x=>x.w/x.h<.45||x.w/x.h>2.3;if(full(a)||!b||full(b)){rows.push(`<div class="art-row solo ${full(a)?'panorama':''}">${piece(a)}</div>`);i++}else{rows.push(`<div class="art-row pair ${rows.length%2?'reverse':''}">${piece(a)}${piece(b)}</div>`);i+=2}}return `<div class="editorial-gallery">${rows.join('')}</div>`}
const projectGrid=list=>`<div class="grid">${list.map(card).join('')}</div>`;
const img=(p)=>p.cover?`<img src="${p.cover}" alt="${p.title}" loading="lazy" decoding="async" width="808" height="632">`:'';
function card(p,i){return `<a class="project" href="#/projeto/${p.id}"><div class="media">${img(p)}</div><div class="project-meta"><div><h3>${p.title}</h3><small>${groups[p.group].name}</small></div><span>${String(i+1).padStart(2,'0')} ↗</span></div></a>`}
function badge(key,i){let g=groups[key];return `<a class="badge" href="#/empresa/${key}" style="--badge:${g.color};--delay:-${i*1.6}s" aria-label="Explorar ${g.name}"><span class="lanyard" aria-hidden="true"></span><div class="badge-body"><span class="slot" aria-hidden="true"></span><span class="badge-stamp" aria-hidden="true">RF<br>DESIGN</span><small>RODRIGO FREITAS / ${String(i+1).padStart(2,'0')}</small><h3>${g.name}</h3><p>${g.role}</p><div class="badge-end"><span>${g.period}</span><span>EXPLORAR ↗</span></div></div></a>`}
function experiences(){return `<section class="section paper" id="experiencias"><div class="section-head"><div><div class="eyebrow">01 / Lugares por onde criei</div><h2>Por onde<br><em>deixei marca.</em></h2></div><p>Cada crachá abre uma parte da minha trajetória. Escolha por onde começar.</p></div><div class="badges">${['point','truther','etec','norte','freelas'].map(badge).join('')}</div></section>`}
const personalProjects={tikjogos:{title:'Tikjogos',type:'Sites & jogos no navegador',url:'https://tikjogos.com.br/',action:'Conhecer o Tikjogos',description:'Um projeto pessoal que conecta meu interesse por desenvolvimento de sites à criação de experiências para jogar com amigos.',tags:['Ideia','Identidade visual','Interface','Programação'],body:'O Tikjogos reúne jogos para amigos, como Impostor, Bomba, Sincronia e Desenho do Impostor. As partidas acontecem no navegador, no celular ou computador, com salas compartilhadas por código.',heading:'Do site à experiência de jogar.',note:'Minha atuação no Tikjogos conecta a ideia do projeto à identidade visual, ao desenho da interface e à programação. Um espaço para transformar criatividade em uma experiência interativa própria.'},obsessao:{title:'Obsessão: O Jogo',type:'Jogo / Roblox Studio',url:'https://play.roblox.com/games/start?placeId=76584738003608',action:'Jogar no Roblox',description:'Um projeto pessoal no Roblox que reúne roteiro, programação, IA e modelagem 3D em uma experiência de suspense.',tags:['Roteiro','Programação','IA','Modelagem 3D','Roblox Studio'],body:'Uma noite dentro de casa se transforma em uma experiência inquietante. A exploração dos ambientes, os diálogos e as interações com objetos dão forma à narrativa.',heading:'Criar um mundo. Contar uma história.',note:'Neste projeto, explorei diferentes etapas do desenvolvimento de um jogo: da construção do roteiro à programação e à modelagem 3D, com uso de IA e do Roblox Studio.'}};
function caseArt(src,alt,caption='',cls=''){return `<figure class="curated-art ${cls}"><a href="${esc(src)}" target="_blank" rel="noopener" aria-label="Ampliar ${esc(alt)}"><img src="${esc(src)}" alt="${esc(alt)}" loading="lazy" decoding="async"></a>${caption?`<figcaption>${caption}</figcaption>`:''}</figure>`}
function caseHeading(n,title,text){return `<div class="chapter-head"><span class="eyebrow">${n}</span><h2>${title}</h2><p>${text}</p></div>`}
function tikGallery(){return `<div class="curated-case tik-case">${caseHeading('01 / Interface','Da sala à partida.','Uma sequência de interfaces: reunir os jogadores, escolher o modo e começar a jogar.')}${caseArt('assets/tikjogos-1.png','Sala de espera do Tikjogos','Sala de espera e seleção de personagens.','wide')}<div class="curated-duo">${caseArt('assets/tikjogos-2.png','Interface do Sincronia','Sincronia — preparação da partida.')}${caseArt('assets/tikjogos-3.png','Interface do STOP','STOP — configurações e início do jogo.')}</div>${caseHeading('02 / Identidade visual','Personagens que entram no jogo.','Desdobramento natalino dos personagens e aplicação em uma peça de divulgação.')}<div class="character-stage">${caseArt('assets/tik-character-1.png','Astronauta natalino com lista de presentes')}${caseArt('assets/tik-character-2.png','Astronauta impostor natalino com presente')}</div>${caseArt('assets/tik-banner.png','Banner Jogue o novo jogo — adivinhe o impostor pelo desenho','Banner de divulgação do jogo de desenho.','banner')}${caseHeading('03 / Aplicativo','TikJogos na Google Play.','Apresentação do aplicativo e materiais de divulgação na loja.')}${caseArt('assets/tikjogos-4.png','Página do TikJogos na Google Play','','wide')}</div>`}
function trutherGallery(items){const art=(i,cls='')=>caseArt(items[i].src,items[i].alt,'',cls);return `<div class="curated-case truther-case">${caseHeading('01 / Marca e produto','Uma identidade, diferentes aplicações.','Marca, ilustração e telas do aplicativo em uma apresentação conjunta.')}<div class="truther-intro">${art(0)}${art(6)}</div>${art(8,'wide')}${caseHeading('02 / Web design','Do contexto ao detalhe.','O site apresentado em uso, seguido pela página completa.')} ${art(1,'wide')}${art(2,'web-page')}${caseHeading('03 / Comunicação','Do digital ao impresso.','Peças de divulgação e aplicação da marca em diferentes formatos.')}<div class="truther-communication">${art(3)}${art(7)}</div>${art(4,'wide')}${caseHeading('04 / PxPay','Outra expressão da marca.','Identidade visual e personagem da PxPay.')} ${art(5,'wide')}</div>`}
function personalVisual(id){return id==='tikjogos'?`<div class="tik-screenshot"><img src="assets/tikjogos-0.png" width="1898" height="908" alt="Página inicial do Tikjogos com criação de sala do Impostor" loading="lazy"></div>`:`<div class="game-art"><img src="assets/obsessao-1.png" width="1902" height="902" alt="Ambiente e personagem de Obsessão: O Jogo" loading="lazy"><span>OBSESSÃO<small>O JOGO / ROBLOX</small></span></div>`}
function personalSection(){return `<section class="section personal" id="pessoais"><div class="section-head"><div><div class="eyebrow">03 / Projetos pessoais</div><h2>Criatividade<br><em>em modo livre.</em></h2></div><p>Meu interesse por desenvolvimento de sites e jogos também vira projeto. Um espaço para experimentar, aprender e criar experiências próprias.</p></div><div class="personal-grid">${Object.entries(personalProjects).map(([id,p],i)=>`<article class="personal-card"><a class="personal-cover" href="#/pessoal/${id}">${personalVisual(id)}</a><div class="personal-info"><span class="eyebrow">0${i+1} / ${p.type}</span><h3><a href="#/pessoal/${id}">${p.title} ↗</a></h3><p>${p.description}</p><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><a class="text-link" href="#/pessoal/${id}">Explorar o projeto ↗</a></div></article>`).join('')}</div></section>`}
function personalDetail(id){const p=personalProjects[id];if(!p){main.innerHTML=personalSection()+cta();return}document.title=p.title+' — Rodrigo Freitas';main.innerHTML=`<div class="page-head"><a class="back" href="#/pessoais">← Projetos pessoais</a><div class="eyebrow">Projeto pessoal / ${p.type}</div><h1>${p.title}</h1><p>${p.description}</p><div class="case-links"><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><a class="text-link" href="${p.url}" target="_blank" rel="noopener">${p.action} ↗</a></div></div><section class="section tight personal-case">${personalVisual(id)}<div class="personal-story"><h2>${p.heading}</h2><div><p>${p.body}</p><p>${p.note}</p></div></div>${id==='obsessao'?`<div class="chapter-head"><span class="eyebrow">Dentro do jogo</span><h2>Ambiente, interação e narrativa.</h2><p>Capturas da experiência no Roblox.</p></div>${mosaic([{src:'assets/obsessao-2.png',w:1918,h:907,alt:'Cozinha e objeto interativo no jogo'},{src:'assets/obsessao-3.png',w:1910,h:902,alt:'Porta bloqueada e diálogo que orienta a exploração'},{src:'assets/obsessao-0.png',w:1898,h:905,alt:'Cena noturna com personagem e caixa de diálogo'}])}`:`${tikGallery()}<div class="personal-features"><div><span>01 / CONECTAR</span><h3>Uma sala, vários amigos.</h3><p>Crie uma sala e compartilhe o código para reunir o grupo.</p></div><div><span>02 / JOGAR</span><h3>Direto no navegador.</h3><p>Jogos acessíveis pelo celular ou computador, sem instalação.</p></div><div><span>03 / EXPLORAR</span><h3>Diferentes formas de brincar.</h3><p>Dedução, desenho, palavras e desafios para jogar em grupo.</p></div></div>`}<div class="case-links"><a class="text-link" href="#/pessoais">← Todos os projetos pessoais</a><a class="text-link" href="${p.url}" target="_blank" rel="noopener">${p.action} ↗</a></div></section>${cta()}`}
function about(){return `<section class="section about me"><div class="eyebrow">04 / Quem está por trás</div><div class="about-body"><figure class="portrait"><img src="assets/rodrigo.webp" width="1266" height="1280" alt="Retrato de Rodrigo Freitas sorrindo" loading="lazy" decoding="async"><figcaption>Rodrigo Freitas — Poá, SP</figcaption></figure><div><h2>Entre a ideia e a forma,<br>existe intenção.</h2><p>Sou Rodrigo Freitas, diretor de arte e designer. Minha trajetória conecta design gráfico, branding, comunicação visual e UX/UI — da construção de uma identidade à experiência de quem interage com ela.</p><div class="tags"><span>Direção de arte</span><span>Branding</span><span>UX/UI</span><span>Design gráfico</span><span>Campanhas</span></div><p>Formado em Design Gráfico pela Universidade Cruzeiro do Sul, com formação em Desenvolvimento de Sistemas pela ETEC de Poá e pós-graduação em UX Design pelo SENAC.</p><a class="text-link" href="https://www.behance.net/rodrigofreitas27" target="_blank" rel="noopener">Mais no Behance ↗</a></div></div></section>`}
function cta(){return `<section class="cta"><small>PRÓXIMO PROJETO / VAMOS TIRAR DO PAPEL?</small><a href="${WA}" target="_blank" rel="noopener" aria-label="Vamos criar — conversar pelo WhatsApp">Deixe sua<br>marca.<span>↗</span></a></section>`}
function home(){let picks=['234995781','truther','245716971','197316331'].map(id=>projects.find(p=>p.id===id)).filter(Boolean);main.innerHTML=`<section class="hero studio-hero"><div class="hero-top eyebrow"><span>Direção de arte / Design gráfico / Digital</span><span><i class="dot"></i>Poá, SP — Brasil</span></div><div class="studio-center"><span class="edition">ARQUIVO CRIATIVO — VOL. 01</span><h1>Design com<br><em>presença.</em></h1><span class="name-tape">Rodrigo Freitas</span><p>Ideias que ganham forma.<br>Marcas que deixam impressão.</p><a class="studio-button" href="#/projetos">Explore os projetos <span>↗</span></a></div><a class="proof proof-one" href="#/projeto/234995781" aria-label="Ver projeto Audi"><span class="proof-label">RF / PROVA DE CRIAÇÃO — 01</span><img src="${projects.find(p=>p.id==='234995781').cover}" alt="Projeto Audi"><span class="proof-caption">DIREÇÃO DE ARTE <b>↗</b></span></a><a class="proof proof-two" href="#/projeto/soft-care" aria-label="Ver projeto Soft Care"><span class="proof-label">RF / PROVA DE CRIAÇÃO — 02</span><img src="assets/soft-77.webp" alt="Projeto Soft Care"><span class="proof-caption">DESIGN EM AÇÃO <b>↗</b></span></a><div class="swatch-fan" aria-hidden="true"><i></i><i></i><i></i><i><span>RF—01<br>VERMELHO<br>CRIATIVO</span></i><b></b></div><div class="studio-tool" aria-hidden="true"><span>RF / DESIGN SYSTEM</span><div><b>↖</b><b>T</b><b>✳</b><b>↗</b></div><small>IDEIA → FORMA → IMPACTO</small></div><div class="hero-baseline"><span>PORTFÓLIO SELECIONADO / 2026</span><a href="#/experiencias">Minha trajetória ↓</a><span>FEITO PARA DEIXAR MARCA.</span></div></section><div class="ticker" aria-hidden="true"><div>${Array(4).fill('<span>DIREÇÃO DE ARTE</span><span>✳</span><span>BRANDING</span><span>✳</span><span>DESIGN DIGITAL</span><span>✳</span>').join('')}</div></div>${experiences()}<section class="section"><div class="section-head"><div><div class="eyebrow">02 / Uma seleção do meu trabalho</div><h2>Ideias fora<br><em>do papel.</em></h2></div><a class="text-link" href="#/projetos">Ver todos os ${projects.length} projetos ↗</a></div><div class="grid">${picks.map(card).join('')}</div></section>${personalSection()}${about()}${cta()}`}
function listing(filter='todos'){const list=projects.filter(p=>filter==='todos'||p.group===filter);main.innerHTML=`<div class="page-head"><a class="back" href="#/">← Início</a><div class="eyebrow">Arquivo criativo / ${projects.length} projetos</div><h1>Trabalho em<br>perspectiva.</h1><p>Campanhas, identidades e experiências digitais. Explore a seleção completa ou escolha uma experiência.</p></div><div class="filters" aria-label="Filtrar por experiência">${['todos','point','truther','norte','freelas'].map(k=>`<button aria-pressed="${k===filter}" data-filter="${k}">${k==='todos'?'Todos':groups[k].name}</button>`).join('')}</div><section class="section tight" aria-live="polite">${projectGrid(list)}</section>${cta()}`;document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{const y=scrollY;listing(b.dataset.filter);scrollTo(0,y);document.querySelector(`[data-filter="${b.dataset.filter}"]`).focus({preventScroll:true})}))}
function company(key){const g=groups[key];if(!g)return home();let list=projects.filter(p=>p.group===key);document.title=g.name+' — Rodrigo Freitas';main.innerHTML=`<div class="page-head"><a class="back" href="#/experiencias">← Todas as experiências</a><div class="eyebrow">${g.role} / ${g.period}</div><h1>${g.name}<span style="color:${g.color}">.</span></h1><p>${g.desc}</p></div><section class="section tight">${list.length?`<div class="section-head"><span class="eyebrow">${list.length} ${list.length===1?'projeto':'projetos'} / seleção</span></div>${projectGrid(list)}`:`<div class="about"><h2>Compartilhar<br>também é criar.</h2><div><p>Na ETEC de Poá, atuei na formação técnica de estudantes, com aulas de informática aplicada ao marketing e orientação de trabalhos de conclusão de curso.</p><div class="timeline"><p><b>Ferramentas digitais</b><br>Softwares de criação e tecnologias utilizadas no mercado.</p><p><b>Orientação de TCCs</b><br>Suporte técnico, criativo e metodológico ao desenvolvimento de projetos.</p><p><b>Formação profissional</b><br>Pensamento estratégico, criatividade e habilidades práticas.</p></div></div></div>`}</section>${cta()}`}
function detail(id){const p=projects.find(p=>p.id===id);if(!p)return home();const g=groups[p.group];document.title=p.title+' — Rodrigo Freitas';main.innerHTML=`<div class="page-head"><a class="back" href="#/empresa/${p.group}">← ${g.name}</a><div class="eyebrow">${g.name} / ${esc(p.discipline||g.role)}</div><h1>${esc(p.title)}</h1>${p.description?`<p>${esc(p.description)}</p>`:''}<div class="case-links"><span class="eyebrow">Projeto selecionado / ${p.items.length} imagens</span>${p.url?`<a class="text-link" href="${p.url}" target="_blank" rel="noopener">Ver projeto no Behance ↗</a>`:''}</div></div><section class="section tight case-content">${p.id==='truther'?trutherGallery(p.items):p.chapters?p.chapters.map((c,i)=>`<section class="chapter"><div class="chapter-head"><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${esc(p.discipline)}</span><h2>${esc(c.title)}</h2><p>${esc(c.text)}</p></div>${mosaic(c.items)}</section>`).join(''):mosaic(p.items)}${p.documents?`<section class="documents"><h2>Explore os materiais completos.</h2>${p.documents.map(d=>`<a href="${esc(d.src)}" target="_blank" rel="noopener"><span>${esc(d.title)}</span><small>PDF · ${d.pages} páginas ↗</small></a>`).join('')}</section>`:''}<div class="case-links"><a class="text-link" href="#/empresa/${p.group}">← Mais de ${g.name}</a><a class="text-link" href="#/projetos">Todos os projetos ↗</a></div></section>${cta()}`}
function route(){const [page,id]=(location.hash.slice(2)||'').split('/');const T={projetos:'Projetos',experiencias:'Experiências',sobre:'Sobre',pessoais:'Projetos pessoais'};document.title=(T[page]?T[page]+' — Rodrigo Freitas':'Rodrigo Freitas — Design em movimento');if(page==='projetos')listing();else if(page==='pessoais')main.innerHTML=personalSection()+cta();else if(page==='pessoal')personalDetail(id);else if(page==='empresa')company(id);else if(page==='projeto')detail(id);else if(page==='experiencias')main.innerHTML=experiences()+cta();else if(page==='sobre')main.innerHTML=about()+cta();else home();document.querySelectorAll('nav a').forEach(a=>a.getAttribute('href')==='#/'+page?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));main.classList.remove('reveal');void main.offsetWidth;main.classList.add('reveal');scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})}
const motion=document.querySelector('#motion');let stored=null;try{stored=localStorage.getItem('rf-motion')}catch(e){}let paused=stored==='off'||matchMedia('(prefers-reduced-motion: reduce)').matches;function motionState(){document.body.classList.toggle('motion-off',paused);motion.textContent=paused?'Ativar movimento':'Pausar movimento';motion.setAttribute('aria-pressed',String(paused))}motionState();motion.onclick=()=>{paused=!paused;try{localStorage.setItem('rf-motion',paused?'off':'on')}catch(e){}motionState()};document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView()});fetch('projects.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{projects=data;const c=document.querySelector('#count');if(c)c.textContent=projects.length;route();addEventListener('hashchange',route)}).catch(()=>main.innerHTML='<section class="section"><h1>Não foi possível carregar os projetos.</h1><p>Atualize a página ou <a href="https://www.behance.net/rodrigofreitas27">visite o Behance ↗</a>.</p></section>');
